/* Base reset */
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body, h1, h2, h3, p, figure { margin: 0; }
img { display: block; max-width: 100%; height: auto; }
ul { margin: 0; padding: 0; list-style: none; }

:root {
  --bg: #ffffff;
  --text: #1b1b1b;
  --muted: #666a6f;
  --line: #e8e8e8;
  --accent: #1e88e5; /* blue */
  --accent-ink: #0b4c8c;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #101214;
    --text: #e6e9ee;
    --muted: #a6acb3;
    --line: #262a2f;
    --accent: #64b5f6;
    --accent-ink: #102a43;
  }
}

html {
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}

/* Typography */
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue",
               Arial, "Noto Sans", "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
  line-height: 1.6;
  color: var(--text);
  background: var(--bg);
}

/* Layout utilities */
.container {
  width: min(1100px, calc(100% - 2rem));
  margin-inline: auto;
}

.section {
  padding: 4rem 0;
}

.section-header {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1.5rem;
}
.section-header h2 {
  font-size: clamp(1.25rem, 0.9rem + 1.8vw, 2rem);
  font-weight: 700;
}
.rule {
  flex: 1 1 auto;
  height: 1px;
  background: var(--line);
}

/* Skip link */
.skip-link {
  position: absolute;
  left: -9999px;
  top: auto;
  width: 1px;
  height: 1px;
  overflow: hidden;
}
.skip-link:focus {
  position: fixed;
  left: 1rem;
  top: 1rem;
  width: auto;
  height: auto;
  padding: 0.5rem 0.75rem;
  background: var(--accent);
  color: #fff;
  border-radius: 6px;
  z-index: 1000;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: color-mix(in srgb, var(--bg) 90%, transparent);
  backdrop-filter: saturate(1.2) blur(6px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 64px;
}
.logo {
  font-weight: 700;
  letter-spacing: 0.5px;
  text-decoration: none;
  color: var(--text);
}
.site-nav ul {
  display: flex;
  gap: 1rem;
}
.site-nav a {
  text-decoration: none;
  color: var(--muted);
  padding: 0.5rem 0.25rem;
  border-radius: 4px;
}
.site-nav a:hover,
.site-nav a:focus-visible {
  color: var(--text);
}

/* Hero */
.hero {
  position: relative;
  padding: 6rem 0 4.5rem;
  background:
    radial-gradient(1200px 600px at 20% 10%, color-mix(in srgb, var(--accent) 12%, transparent) 0%, transparent 60%),
    radial-gradient(900px 500px at 80% 20%, color-mix(in srgb, var(--accent) 10%, transparent) 0%, transparent 60%),
    var(--bg);
  border-bottom: 1px solid var(--line);
}
.hero-inner {
  max-width: 800px;
}
.eyebrow {
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.85rem;
  margin-bottom: 0.5rem;
}
.hero h1 {
  font-size: clamp(2rem, 1.4rem + 3vw, 3.25rem);
  line-height: 1.2;
  margin-bottom: 0.5rem;
}
.tagline {
  font-size: clamp(1rem, 0.95rem + 0.5vw, 1.25rem);
  color: var(--muted);
  max-width: 55ch;
}
.actions {
  display: flex;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

/* Buttons */
.btn {
  display: inline-block;
  padding: 0.65rem 1rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--text);
  text-decoration: none;
  background: transparent;
  transition: transform 0.15s ease, background 0.2s ease, border-color 0.2s ease;
}
.btn:hover {
  transform: translateY(-1px);
}
.btn.primary {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}
.btn.primary:hover {
  background: color-mix(in srgb, var(--accent) 90%, #000 10%);
}

/* About */
.about-body {
  display: grid;
  gap: 1rem;
}
.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.25rem;
}
.tags li {
  padding: 0.25rem 0.6rem;
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 0.9rem;
  color: var(--muted);
}

/* Gallery */
.grid {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}
.grid-item {
  overflow: hidden;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: color-mix(in srgb, var(--bg) 90%, transparent);
}
.grid-item img {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  transform: scale(1.01);
  transition: transform 0.3s ease;
}
.grid-item:hover img {
  transform: scale(1.05);
}

/* Contact */
.contact-intro {
  color: var(--muted);
  margin-bottom: 1rem;
}
form {
  max-width: 680px;
}
.field {
  display: grid;
  gap: 0.4rem;
  margin-bottom: 1rem;
}
label {
  font-weight: 600;
}
input, textarea {
  width: 100%;
  padding: 0.7rem 0.8rem;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: var(--bg);
  color: var(--text);
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
input:focus-visible, textarea:focus-visible {
  border-color: color-mix(in srgb, var(--accent) 70%, var(--line));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 25%, transparent);
}
.error {
  color: #c62828;
  font-size: 0.9rem;
  min-height: 1.1em;
}
.form-note {
  color: var(--muted);
  font-size: 0.95rem;
  margin-top: 0.5rem;
}
.form-status {
  margin-top: 0.5rem;
  font-weight: 600;
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--line);
  padding: 2rem 0;
}
.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}
.socials {
  display: flex;
  gap: 1rem;
}
.socials a {
  color: var(--muted);
  text-decoration: none;
}
.socials a:hover,
.socials a:focus-visible {
  color: var(--text);
}

/* Small screens adjustments */
@media (max-width: 600px) {
  .site-nav ul { gap: 0.75rem; }
  .hero { padding: 4.5rem 0 3rem; }
}
