```javascript
// Smooth internal link scrolling (fallback for browsers without CSS smooth behavior)
document.addEventListener('DOMContentLoaded', () => {
  const navLinks = document.querySelectorAll('a[href^="#"]');
  navLinks.forEach(link => {
    link.addEventListener('click', e => {
      const targetId = link.getAttribute('href').slice(1);
      const targetEl = document.getElementById(targetId);
      if (targetEl) {
        e.preventDefault();
        targetEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
        // Move focus to the target for accessibility
        targetEl.setAttribute('tabindex', '-1');
        targetEl.focus({ preventScroll: true });
      }
    });
  });

  // Footer year
  const yearEl = document.getElementById('year');
  if (yearEl) yearEl.textContent = new Date().getFullYear();

  // Contact form handling (frontend only)
  const form = document.getElementById('contact-form');
  const statusEl = document.querySelector('.form-status');

  function setError(field, msg) {
    const container = field.closest('.field');
    const errorEl = container?.querySelector('.error');
    if (errorEl) errorEl.textContent = msg || '';
    field.setAttribute('aria-invalid', msg ? 'true' : 'false');
  }

  function validateEmail(email) {
    // Simple RFC5322-ish email pattern for demo
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }

  if (form) {
    form.addEventListener('submit', e => {
      e.preventDefault();
      const name = form.querySelector('#name');
      const email = form.querySelector('#email');
      const message = form.querySelector('#message');
      const submitBtn = form.querySelector('button[type="submit"]');

      let valid = true;

      // Name
      if (!name.value.trim()) {
        setError(name, 'Please enter your name.');
        valid = false;
      } else {
        setError(name, '');
      }

      // Email
      if (!email.value.trim()) {
        setError(email, 'Please enter your email.');
        valid = false;
      } else if (!validateEmail(email.value.trim())) {
        setError(email, 'Please enter a valid email address.');
        valid = false;
      } else {
        setError(email, '');
      }

      // Message
      if (!message.value.trim()) {
        setError(message, 'Please enter a message.');
        valid = false;
      } else {
        setError(message, '');
      }

      if (!valid) {
        statusEl.textContent = 'Please fix the errors and try again.';
        return;
      }

      // Simulate sending
      statusEl.textContent = 'Sending...';
      submitBtn.disabled = true;

      setTimeout(() => {
        statusEl.textContent = 'Thanks for reaching out! I’ll get back to you soon.';
        form.reset();
        submitBtn.disabled = false;
      }, 900);
    });
  }
});
