  font-size: 0.95rem;
  color: var(--muted);
}
.btn.chip.active {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

/* About */
.about-body {
  display: grid;
  gap: 1rem;
}
.tags {
  display: flex;
  flex-wrap: wrap;
