}
.tags li {
  padding: 0.25rem 0.6rem;
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 0.9rem;
  color: var(--muted);
}

/* Gallery */
.grid {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}
.grid-item {
  overflow: hidden;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: color-mix(in srgb, var(--bg) 90%, transparent);
  cursor: zoom-in;
  transition: opacity 250ms ease, transform 250ms ease;
}
.grid-item img {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  transform: scale(1.01);
  transition: transform 0.3s ease;
}
.grid-item:hover img {
  transform: scale(1.05);
}
/* Smooth filter animation */
.grid-item.filter-out {
  opacity: 0;
  transform: scale(0.98);
  pointer-events: none;
}

/* Contact */
.contact-intro {
  color: var(--muted);
  margin-bottom: 1rem;
}
form {
  max-width: 680px;
}
.field {
