  gap: 0.4rem;
  margin-bottom: 1rem;
}
label {
  font-weight: 600;
}
input, textarea {
  width: 100%;
  padding: 0.7rem 0.8rem;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: var(--bg);
