}
.error {
  color: #c62828;
  font-size: 0.9rem;
  min-height: 1.1em;
}
.form-note {
  color: var(--muted);
  font-size: 0.95rem;
  margin-top: 0.5rem;
}
.form-status {
  margin-top: 0.5rem;
  font-weight: 600;
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--line);
  padding: 2rem 0;
}
.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}
.socials {
  display: flex;
  gap: 1rem;
}
.socials a {
  color: var(--muted);
  text-decoration: none;
}
.socials a:hover,
.socials a:focus-visible {
  color: var(--text);
}

/* Lightbox */
.lightbox[hidden] { display: none; }
.lightbox {
  position: fixed;
  inset: 0;
  z-index: 999;
  background: var(--overlay);
  display: grid;
  place-items: center;
  padding: 1rem;
}
.lightbox-inner {
  position: relative;
  width: min(100%, 1000px);
  max-height: 90vh;
  display: grid;
  grid-template-areas:
    "figure"
    "meta";
  gap: 0.75rem;
}
.lightbox-figure {
  grid-area: figure;
  margin: 0;
  border-radius: 12px;
  overflow: hidden;
  background: var(--bg);
  border: 1px solid var(--line);
}
.lightbox-image {
  display: block;
  width: 100%;
  height: auto;
  max-height: 70vh;
  object-fit: contain;
  background: var(--bg);
}
.lightbox-meta {
  grid-area: meta;
  display: grid;
  gap: 0.25rem;
  color: var(--text);
}
.lightbox-title {
  font-size: 1.1rem;
  font-weight: 700;
}
.lightbox-caption {
  color: var(--muted);
}

/* Controls */
.lightbox-close {
  position: absolute;
  top: -0.5rem;
  right: -0.5rem;
  transform: translate(0, -100%);
  background: var(--bg);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 999px;
  width: 40px;
  height: 40px;
  font-size: 1.5rem;
  line-height: 1;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.lightbox-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: color-mix(in srgb, var(--bg) 85%, transparent);
  border: 1px solid var(--line);
  color: var(--text);
  width: 44px;
  height: 44px;
  border-radius: 999px;
  cursor: pointer;
  font-size: 1.25rem;
  display: grid;
  place-items: center;
}
.lightbox-nav.prev { left: -0.5rem; transform: translate(-100%, -50%); }
.lightbox-nav.next { right: -0.5rem; transform: translate(100%, -50%); }

@media (max-width: 600px) {
  .site-nav ul { gap: 0.75rem; }
  .hero { padding: 4.5rem 0 3rem; }
  .lightbox-image { max-height: 60vh; }
}
